"""Bahasa Melayu — para nabi (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Nabi manakah yang membina bahtera atas perintah Allah?", ["Nuh", "Ibrahim", "Musa", "Yusuf"], "Allah memerintahkan Nuh membina bahtera untuk menyelamatkan orang beriman daripada banjir besar."),
"prophets_002": ("Nabi manakah yang dicampakkan ke dalam api yang Allah jadikan sejuk dan selamat baginya?", ["Ibrahim", "Nuh", "Daud", "Ayub"], "Allah memerintahkan api menjadi sejuk dan selamat bagi Ibrahim."),
"prophets_003": ("Nabi manakah yang ditelan oleh seekor ikan yang besar?", ["Yunus", "Ilyas", "Idris", "Zakaria"], "Yunus ditelan ikan selepas meninggalkan kaumnya dalam keadaan marah; Allah mengampuninya."),
"prophets_004": ("Nabi manakah yang mentafsirkan mimpi raja tentang tujuh ekor lembu gemuk dan tujuh ekor lembu kurus?", ["Yusuf", "Yaakub", "Ismail", "Ishak"], "Yusuf mentafsirkan mimpi raja, meramalkan tujuh tahun kemewahan diikuti tujuh tahun kemarau."),
"prophets_005": ("Nabi manakah yang, menurut al-Quran, diajak bicara secara langsung oleh Allah?", ["Musa", "Harun", "Yusuf", "Sulaiman"], "Al-Quran menyatakan bahawa Allah berbicara kepada Musa secara langsung."),
"prophets_006": ("Nabi manakah yang memahami bahasa burung?", ["Sulaiman", "Daud", "Yunus", "Yusuf"], "Allah mengajar Sulaiman bahasa burung."),
"prophets_007": ("Nabi manakah yang diberi kitab yang dinamakan Zabur?", ["Daud", "Musa", "Isa", "Ibrahim"], "Al-Quran menyebut bahawa Zabur diberikan kepada Daud."),
"prophets_008": ("Nabi manakah yang dilahirkan tanpa bapa, dengan firman Allah «Jadilah, maka jadilah ia»?", ["Isa", "Yahya", "Ismail", "Ishak"], "Al-Quran menggambarkan kelahiran Isa yang ajaib tanpa bapa, hanya dengan firman Allah."),
"prophets_009": ("Surah manakah dalam al-Quran yang dinamakan sempena ibu seorang nabi?", ["Maryam", "Yusuf", "Nuh", "Hud"], "Surah 19, Maryam, dinamakan sempena ibu Nabi Isa."),
"prophets_010": ("Nabi manakah yang diuji dengan penyakit yang teruk dan dipuji kerana kesabarannya?", ["Ayub", "Zakaria", "Yahya", "Idris"], "Ayub tetap sabar sepanjang ujian yang amat berat, dan Allah mengurniakannya ganjaran."),
"prophets_011": ("Kepada siapakah Allah memerintahkan para malaikat sujud, sebagai tanda penghormatan?", ["Adam", "Nuh", "Ibrahim", "Musa"], "Allah memerintahkan para malaikat sujud kepada Adam sebagai tanda penghormatan, bukan penyembahan."),
"prophets_012": ("Nabi manakah yang digelar «Khalilullah», sahabat karib Allah?", ["Ibrahim", "Musa", "Isa", "Muhammad ﷺ"], "Al-Quran menggambarkan Ibrahim sebagai sahabat karib (khalil) Allah."),
"prophets_013": ("Nabi manakah yang dicampakkan ke dalam perigi oleh saudara-saudaranya?", ["Yusuf", "Bunyamin", "Yaakub", "Ismail"], "Saudara-saudara Yusuf mencampakkannya ke dalam perigi kerana cemburu."),
"prophets_014": ("Kaum nabi manakah yang dimusnahkan oleh banjir besar selepas menolaknya?", ["Nuh", "Hud", "Salih", "Syuaib"], "Kaum Nuh ditenggelamkan banjir besar selepas berterusan menolak dakwahnya."),
"prophets_015": ("Nabi manakah yang menyaksikan laut terbelah untuk menyelamatkan kaumnya daripada Firaun?", ["Musa", "Harun", "Yusuf", "Ismail"], "Allah memerintahkan Musa memukul laut, lalu ia terbelah supaya orang beriman dapat melintas."),
"prophets_016": ("Nabi manakah yang, bersama bapanya Daud, mengadili kes ladang yang dimakan kambing?", ["Sulaiman", "Ismail", "Yusuf", "Ishak"], "Al-Quran menceritakan bahawa Sulaiman dan Daud mengadili kes ini, dan Allah mengurniakan Sulaiman kefahaman tentangnya."),
"prophets_017": ("Ibu nabi manakah yang diperintahkan meletakkan bayinya ke dalam sungai?", ["Musa", "Isa", "Yusuf", "Ismail"], "Allah mengilhamkan ibu Musa untuk meletakkannya dalam peti di sungai bagi melindunginya."),
"prophets_018": ("Unta betina nabi manakah yang menjadi tanda kepada kaumnya, Tsamud?", ["Salih", "Hud", "Syuaib", "Lut"], "Allah menghantar seekor unta betina sebagai tanda kepada kaum Tsamud melalui Nabi Salih."),
"prophets_019": ("Nabi manakah yang Allah ajarkan nama-nama segala sesuatu?", ["Adam", "Nuh", "Ibrahim", "Musa"], "Allah mengajar Adam nama-nama segala sesuatu, dan para malaikat mengakui kebijaksanaan Allah."),
"prophets_020": ("Nabi manakah yang berbicara kepada manusia ketika masih bayi dalam buaian?", ["Isa", "Yahya", "Yusuf", "Ismail"], "Bayi Isa berbicara dari buaian: «Aku hamba Allah; Dia telah memberiku Kitab.»"),
"prophets_021": ("Bersama anak yang manakah Ibrahim meninggikan asas Kaabah?", ["Ismail", "Ishak", "Yaakub", "Yusuf"], "«Dan ketika Ibrahim dan Ismail meninggikan asas Baitullah…»: mereka membinanya bersama."),
"prophets_022": ("Anak manakah yang dikhabarkan kepada Nabi Zakaria pada usia tuanya?", ["Yahya", "Isa", "Ismail", "Ishak"], "«Wahai Zakaria, Kami khabarkan kepadamu berita gembira tentang seorang anak lelaki bernama Yahya.»"),
"prophets_023": ("Menjadi apakah tongkat Musa apabila Allah menyuruhnya mencampakkannya?", ["Seekor ular yang bergerak", "Seekor burung", "Mata air", "Cahaya"], "«Campakkanlah, wahai Musa!» Dia mencampakkannya, lalu ia menjadi seekor ular yang bergerak pantas."),
"prophets_024": ("Dalam mimpinya, apakah yang dilihat Yusuf muda sujud kepadanya?", ["Sebelas bintang, matahari dan bulan", "Tujuh ekor lembu gemuk", "Hujan emas", "Taman kurma"], "Yusuf melihat sebelas bintang serta matahari dan bulan sujud kepadanya: tanda takdirnya."),
"prophets_025": ("Kepada kaum manakah Nabi Hud diutuskan?", ["Kaum 'Ad", "Kaum Tsamud", "Penduduk Madyan", "Kaum Firaun"], "«Dan kepada kaum 'Ad, saudara mereka Hud…»: dia menyeru mereka menyembah Allah semata-mata."),
"prophets_026": ("Kepada kaum manakah Nabi Syuaib diutuskan?", ["Penduduk Madyan", "Kaum 'Ad", "Kaum Tsamud", "Kaum Nuh"], "«Dan kepada Madyan, saudara mereka Syuaib…»: dia memerintahkan mereka menyempurnakan sukatan dan timbangan."),
"prophets_027": ("Nabi manakah yang digelar «Dzun-Nun» (orang yang bersama ikan) dalam al-Quran?", ["Yunus", "Musa", "Sulaiman", "Ayub"], "«Dan Dzun-Nun, ketika dia pergi dalam keadaan marah…»: inilah Yunus, yang kemudian ditelan ikan."),
"prophets_028": ("Dalam surah manakah Musa mengembara untuk belajar daripada seorang hamba yang Allah kurniakan ilmu khusus?", ["Al-Kahfi", "Yusuf", "Maryam", "An-Naml"], "Dalam surah Al-Kahfi, Musa menemani seorang hamba yang berilmu dan belajar bersabar terhadap perkara yang belum difahaminya."),
"prophets_029": ("Nabi manakah yang paling kerap disebut namanya dalam al-Quran?", ["Musa", "Ibrahim", "Nuh", "Isa"], "Musa ialah nabi yang paling kerap dinamakan dalam al-Quran; kisahnya bersama Firaun berulang banyak kali."),
"prophets_030": ("Berapa orang nabi yang disebut namanya dalam al-Quran?", ["25", "10", "50", "99"], "Dua puluh lima orang nabi dinamakan dalam al-Quran, daripada Adam hingga Muhammad ﷺ."),
"prophets_031": ("Dengan izin Allah, nabi manakah yang menyembuhkan orang buta dan pesakit kusta?", ["Isa", "Musa", "Daud", "Yunus"], "Isa menyembuhkan orang buta dan pesakit kusta dengan izin Allah: satu tanda kepada kaumnya."),
"prophets_032": ("Menurut al-Quran, berapa lama Nuh tinggal dalam kalangan kaumnya menyeru mereka kepada Allah?", ["950 tahun", "100 tahun", "300 tahun", "40 tahun"], "«Dia tinggal dalam kalangan mereka seribu tahun kurang lima puluh»: 950 tahun seruan yang penuh sabar."),
"prophets_033": ("Menurut al-Quran, daripada apakah Allah menciptakan Adam?", ["Daripada tanah liat", "Daripada cahaya", "Daripada api", "Daripada air"], "Allah berfirman kepada para malaikat: «Aku akan menciptakan manusia daripada tanah liat.»"),
"prophets_034": ("Siapakah yang menggoda Adam dan isterinya supaya makan daripada pokok yang dilarang?", ["Syaitan (Iblis)", "Seorang malaikat", "Seekor burung", "Seorang raja"], "Syaitan membisikkan kepada mereka supaya mereka makan daripada pokok yang Allah larang."),
"prophets_035": ("Apakah alasan Iblis enggan sujud kepada Adam?", ["«Aku lebih baik daripadanya: Engkau menciptakanku daripada api dan dia daripada tanah liat»", "Dia tidak tahu siapa Adam", "Dia takut kepada para malaikat", "Dia sedang tidur"], "Iblis enggan kerana sombong: «Engkau menciptakanku daripada api, dan dia Engkau ciptakan daripada tanah liat.»"),
"prophets_036": ("Selepas pembunuhan antara dua anak Adam, haiwan apakah yang Allah hantar untuk menunjukkan cara mengebumikan jenazah?", ["Seekor gagak", "Seekor anjing", "Seekor merpati", "Seekor musang"], "Allah menghantar seekor gagak yang menggali tanah untuk menunjukkan kepada pembunuh itu cara menyembunyikan jenazah saudaranya."),
"prophets_037": ("Apakah yang al-Quran katakan tentang Nabi Idris?", ["Allah mengangkatnya ke darjat yang tinggi", "Dia membina bahtera", "Dia ditelan ikan", "Dia berbicara dengan semut"], "«Dan Kami mengangkatnya ke darjat yang tinggi.»"),
"prophets_038": ("Apakah yang dilakukan anak Nuh apabila bapanya memanggilnya naik ke bahtera?", ["Dia enggan dan berkata dia akan berlindung di gunung", "Dia naik dahulu", "Dia membina bahteranya sendiri", "Dia pergi mengumpulkan haiwan"], "Dia berkata: «Aku akan berlindung di sebuah gunung»; lalu ombak menenggelamkannya."),
"prophets_039": ("Di gunung manakah bahtera Nuh berlabuh, menurut al-Quran?", ["Gunung Judi", "Gunung Sinai", "Gunung Uhud", "Gunung Arafah"], "«Dan bahtera itu berlabuh di atas Judi.»"),
"prophets_040": ("Apakah yang Allah perintahkan Nuh muatkan ke dalam bahtera?", ["Sepasang daripada setiap jenis, dan orang beriman", "Hanya keluarganya", "Hanya burung", "Emas dan perak"], "«Muatkanlah ke dalamnya sepasang daripada setiap jenis, dan keluargamu… dan sesiapa yang beriman.»"),
"prophets_041": ("Apakah yang dilakukan pembesar kaum Nuh apabila melihatnya membina bahtera?", ["Mereka mengejeknya", "Mereka membantunya", "Mereka membawakan kayu", "Mereka solat bersamanya"], "Setiap kali pembesar kaumnya lalu, mereka mengejeknya."),
"prophets_042": ("Bagaimanakah al-Quran menggambarkan Nuh dalam surah Al-Isra?", ["Seorang hamba yang bersyukur", "Seorang raja yang perkasa", "Seorang pengembara yang hebat", "Seorang lelaki yang pendiam"], "«Sesungguhnya dia adalah hamba yang bersyukur.»"),
"prophets_043": ("Bagaimanakah kaum 'Ad, yang Hud diutuskan kepada mereka, dimusnahkan?", ["Dengan angin yang amat kencang lagi ganas", "Dengan banjir besar", "Dengan hujan batu", "Dengan gempa bumi"], "«Adapun kaum 'Ad, mereka dimusnahkan dengan angin yang menderu lagi amat kencang.»"),
"prophets_044": ("Apakah yang menimpa Tsamud, kaum Salih?", ["Suara jeritan yang dahsyat", "Banjir besar", "Kebuluran", "Kawanan belalang"], "«Dan jeritan itu menimpa orang-orang yang zalim.»"),
"prophets_045": ("Apakah nama bapa Ibrahim yang disebut dalam al-Quran?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim berkata kepada bapanya Azar: adakah engkau menjadikan berhala sebagai tuhan?»"),
"prophets_046": ("Selepas memecahkan berhala-berhala, yang manakah Ibrahim biarkan utuh?", ["Yang paling besar", "Yang paling kecil", "Yang diperbuat daripada emas", "Tiada, dia memecahkan semuanya"], "Dia menghancurkannya berkeping-keping, kecuali yang paling besar, supaya kaumnya bertanya kepadanya."),
"prophets_047": ("Selepas melihat bintang, bulan dan kemudian matahari terbenam, apakah yang Ibrahim isytiharkan?", ["«Aku tidak suka kepada yang terbenam»", "«Matahari adalah tuhanku»", "«Bulan paling indah»", "«Aku akan tidur»"], "Setiap kali satu daripadanya terbenam dia berkata: «Aku tidak suka kepada yang terbenam», lalu dia berpaling kepada Pencipta."),
"prophets_048": ("Berapa ekor burung yang Allah suruh Ibrahim ambil, untuk menunjukkan cara Dia menghidupkan yang mati?", ["Empat", "Dua", "Tujuh", "Dua belas"], "«Ambillah empat ekor burung… kemudian panggillah mereka: mereka akan datang kepadamu dengan segera.»"),
"prophets_049": ("Apakah yang Ibrahim hidangkan kepada tetamunya, para malaikat yang datang membawa berita gembira?", ["Anak lembu panggang", "Kurma", "Susu", "Roti dan madu"], "«Dia tidak lengah membawa anak lembu panggang.»"),
"prophets_050": ("Apakah berita gembira yang dibawa para malaikat kepada isteri Ibrahim?", ["Kelahiran Ishak", "Satu perjalanan", "Kekayaan yang besar", "Hujan yang lebat"], "«Kami menyampaikan berita gembira kepadanya tentang Ishak, dan selepas Ishak, Yaakub.»"),
"prophets_051": ("Bagaimanakah reaksi anak Ibrahim apabila bapanya menceritakan mimpi menyembelihnya?", ["Dia menerima: «Lakukanlah apa yang diperintahkan kepadamu»", "Dia melarikan diri", "Dia menangis dan enggan", "Dia bersembunyi"], "Dia berkata: «Wahai ayahku, lakukanlah apa yang diperintahkan kepadamu.» Dan Allah menebusnya dengan sembelihan yang besar."),
"prophets_052": ("Dalam doanya, di manakah Ibrahim berkata dia menempatkan sebahagian keluarganya?", ["Di lembah yang tiada tanaman, berhampiran Rumah Suci", "Di tebing Sungai Nil", "Di dalam hutan", "Di sebuah pulau"], "«Aku telah menempatkan sebahagian zuriatku di lembah yang tiada tanaman berhampiran Rumah-Mu yang Suci.»"),
"prophets_053": ("Apakah yang Ibrahim pohon untuk kota Makkah dalam doanya?", ["Agar ia menjadi kota yang aman dan penduduknya diberi buah-buahan", "Agar ia menjadi kerajaan", "Agar sentiasa hujan di sana", "Agar ia mempunyai sungai"], "«Wahai Tuhanku, jadikanlah ini kota yang aman dan berikanlah rezeki buah-buahan kepada penduduknya.»"),
"prophets_054": ("Ketika meninggikan Kaabah, Ibrahim dan Ismail memohon Allah mengutuskan dalam kalangan zuriat mereka…?", ["Seorang rasul daripada kalangan mereka, yang membacakan ayat-ayat-Nya", "Seorang raja", "Sebuah tentera", "Sebuah harta karun"], "«Wahai Tuhan kami, utuskanlah dalam kalangan mereka seorang rasul daripada kalangan mereka sendiri yang membacakan ayat-ayat-Mu kepada mereka.»"),
"prophets_055": ("Al-Quran menyatakan seorang nabi, seorang diri, adalah «satu umat». Siapakah dia?", ["Ibrahim", "Nuh", "Musa", "Sulaiman"], "«Sesungguhnya Ibrahim adalah satu umat, taat kepada Allah, lurus.»"),
"prophets_056": ("Kerana sifat apakah al-Quran memuji Ismail dalam surah Maryam?", ["Dia benar dalam janjinya", "Dia sangat kaya", "Dia seorang raja", "Dia pandai berenang"], "«Sesungguhnya dia benar dalam janjinya, dan dia adalah seorang rasul dan nabi.»"),
"prophets_057": ("Azab apakah yang menimpa kaum Lut?", ["Hujan batu daripada tanah yang dibakar", "Banjir besar", "Kawanan serangga", "Kemarau"], "«Kami jadikan kota itu terbalik dan Kami hujani dengan batu daripada tanah yang dibakar.»"),
"prophets_058": ("Isteri dua orang nabi manakah yang al-Quran jadikan contoh kekufuran?", ["Nuh dan Lut", "Ibrahim dan Musa", "Daud dan Sulaiman", "Ayub dan Yunus"], "«Allah menjadikan contoh bagi orang kafir: isteri Nuh dan isteri Lut.»"),
"prophets_059": ("Siapakah bapa Yaakub?", ["Ishak", "Ismail", "Ibrahim", "Yusuf"], "Para malaikat mengkhabarkan kepada isteri Ibrahim «Ishak, dan selepas Ishak, Yaakub»."),
"prophets_060": ("Apakah yang berlaku kepada penglihatan Yaakub kerana menangisi Yusuf?", ["Matanya menjadi putih", "Dia lebih nampak pada waktu malam", "Tiada apa yang berubah", "Dia kehilangan sebelah mata"], "«Matanya menjadi putih kerana kesedihan, dan dia menahannya.»"),
"prophets_061": ("Apakah yang memulihkan penglihatan Yaakub?", ["Baju Yusuf yang dilemparkan ke wajahnya", "Sejenis tumbuhan", "Air Zamzam", "Sejenis salap"], "Yusuf berkata: «Lemparkanlah bajuku ini ke wajah ayahku; dia akan dapat melihat semula.»"),
"prophets_062": ("Apakah yang Yusuf lebih sukai daripada tunduk kepada perkara yang dia diajak secara salah?", ["Penjara", "Buangan", "Kekayaan", "Diam"], "«Wahai Tuhanku, penjara lebih aku sukai daripada apa yang mereka ajak aku kepadanya.»"),
"prophets_063": ("Di dalam penjara, dua orang pemuda menceritakan mimpi mereka kepada Yusuf. Apakah yang dilihat salah seorang daripada mereka?", ["Dia memerah anggur", "Dia terbang", "Dia menggembala kambing", "Dia menggali perigi"], "Seorang melihat dirinya memerah arak, seorang lagi menjunjung roti di atas kepalanya yang dimakan burung."),
"prophets_064": ("Berapa tahun kemewahan dan kemudian kemarau yang Yusuf ramalkan kepada raja?", ["Tujuh dan tujuh", "Tiga dan tiga", "Sepuluh dan sepuluh", "Satu dan satu"], "«Kamu akan bercucuk tanam tujuh tahun… kemudian akan datang tujuh tahun yang sukar.»"),
"prophets_065": ("Jawatan apakah yang Yusuf pohon daripada raja Mesir?", ["Perbendaharaan negeri", "Ketua tentera", "Takhta", "Khazanah emas"], "«Lantiklah aku menguruskan perbendaharaan negeri: aku pandai menjaga lagi berpengetahuan.»"),
"prophets_066": ("Apakah yang Yusuf letakkan dalam bekalan adiknya untuk mengekalkannya di sisinya?", ["Piala minuman raja", "Sebuah beg emas", "Sepucuk surat", "Bajunya"], "«Dia memasukkan piala minuman ke dalam karung adiknya.»"),
"prophets_067": ("Apakah nasihat Yaakub kepada anak-anaknya sebelum mereka memasuki Mesir?", ["Masuk melalui pintu-pintu yang berlainan", "Bermusafir pada waktu malam", "Menyamar", "Membawa hadiah"], "«Janganlah kamu masuk melalui satu pintu, tetapi masuklah melalui pintu-pintu yang berlainan.»"),
"prophets_068": ("Mengapakah saudara-saudara Yusuf datang ke Mesir ketika dia memerintah di sana?", ["Untuk mendapatkan bekalan semasa kemarau", "Untuk mencarinya", "Untuk menunaikan ibadah", "Untuk menjual unta"], "Saudara-saudaranya datang untuk mendapatkan gandum; mereka masuk menemuinya dan tidak mengenalinya."),
"prophets_069": ("Di rumah siapakah bayi Musa diambil selepas diletakkan di sungai?", ["Firaun", "Seorang gembala", "Seorang nelayan", "Seorang pedagang"], "Keluarga Firaun memungutnya, agar dia kelak menjadi musuh dan kesedihan bagi mereka."),
"prophets_070": ("Bagaimanakah bayi Musa akhirnya kembali kepada ibunya?", ["Dia menolak setiap ibu susuan, dan kakaknya mencadangkan ibunya", "Firaun memulangkannya kerana belas kasihan", "Ibunya mencurinya pada waktu malam", "Seorang malaikat membawanya"], "Allah menjadikannya enggan menyusu daripada ibu-ibu susuan; kakaknya mencadangkan sebuah keluarga: itulah ibunya, yang menyusukannya."),
"prophets_071": ("Mengapakah Musa terpaksa meninggalkan Mesir dengan segera, sebelum tugas kenabiannya?", ["Dia telah membunuh seorang lelaki tanpa sengaja dengan satu tumbukan", "Dia telah mencuri dari istana", "Dia enggan membayar cukai", "Dia telah menghina Firaun"], "Dia menumbuk seorang Mesir yang bergaduh dengan seorang lelaki daripada kaumnya lalu membunuhnya; dia serta-merta menyesal."),
"prophets_072": ("Siapakah yang memberi amaran kepada Musa bahawa para pembesar berkomplot untuk membunuhnya?", ["Seorang lelaki yang datang berlari dari hujung kota", "Ibunya", "Harun", "Seorang askar"], "«Seorang lelaki datang berlari dari hujung kota: mereka berkomplot untuk membunuhmu, maka keluarlah!»"),
"prophets_073": ("Setibanya di Madyan, apakah yang Musa lakukan untuk dua orang wanita di tempat minum ternakan?", ["Dia memberi minum ternakan mereka", "Dia menjual seekor unta kepada mereka", "Dia membina rumah untuk mereka", "Dia mengajar mereka membaca"], "Dia memberi minum ternakan mereka, kemudian berteduh di tempat yang redup sambil berdoa kepada Allah."),
"prophets_074": ("Berapa tahun orang tua di Madyan meminta Musa bekerja untuk mengahwini anaknya?", ["Lapan, dan sepuluh jika dia mahu", "Satu", "Empat puluh", "Tiga"], "«Engkau akan bekerja denganku selama lapan tahun; jika engkau cukupkan sepuluh, itu atas kerelaanmu.»"),
"prophets_075": ("Apakah yang Allah perintahkan Musa tanggalkan di lembah suci Tuwa?", ["Kasutnya", "Jubahnya", "Tongkatnya", "Serbannya"], "«Tanggalkanlah kasutmu: engkau berada di lembah suci Tuwa.»"),
"prophets_076": ("Apakah tanda kedua yang diberikan kepada Musa, selepas tongkat?", ["Tangannya keluar putih, tanpa cacat", "Dia boleh terbang", "Suaranya menjadi guruh", "Dia dapat melihat pada waktu malam"], "«Kepitkanlah tanganmu ke rusukmu: ia akan keluar putih, tanpa penyakit.»"),
"prophets_077": ("Apakah yang Musa pohon daripada Allah sebelum menghadap Firaun?", ["Agar dilapangkan dadanya dan dilepaskan kekakuan lidahnya", "Sebuah tentera", "Emas", "Seekor kuda yang pantas"], "«Wahai Tuhanku, lapangkanlah dadaku, mudahkanlah urusanku, dan lepaskanlah kekakuan lidahku.»"),
"prophets_078": ("Siapakah yang Musa pohon daripada Allah sebagai pembantu dalam tugasnya?", ["Saudaranya Harun", "Anaknya", "Bapa mertuanya", "Seorang malaikat"], "«Jadikanlah untukku seorang pembantu daripada keluargaku: Harun, saudaraku.»"),
"prophets_079": ("Apakah yang dilakukan ahli sihir Firaun apabila tongkat Musa menelan tipu daya mereka?", ["Mereka sujud dan beriman", "Mereka melarikan diri", "Mereka ketawa", "Mereka menyerang Musa"], "Para ahli sihir itu tersungkur sujud: «Kami beriman kepada Tuhan sekalian alam, Tuhan Musa dan Harun.»"),
"prophets_080": ("Antara berikut, wabak manakah yang al-Quran senaraikan sebagai yang dihantar terhadap kaum Firaun?", ["Belalang", "Salji", "Serigala", "Api"], "«Kami hantarkan kepada mereka taufan, belalang, kutu, katak dan darah.»"),
"prophets_081": ("Menurut al-Quran, apakah yang Allah lakukan terhadap jasad Firaun selepas dia lemas?", ["Memeliharanya sebagai tanda", "Melenyapkannya", "Membakarnya", "Memulangkannya kepada kaumnya"], "«Pada hari ini Kami selamatkan jasadmu, supaya engkau menjadi tanda bagi orang yang datang selepasmu.»"),
"prophets_082": ("Menurut al-Quran, apakah yang dipohon isteri Firaun yang beriman daripada Allah?", ["Sebuah rumah di sisi-Nya di syurga", "Seorang anak lelaki", "Kematian Firaun", "Sebuah kerajaan"], "«Wahai Tuhanku, binalah untukku sebuah rumah di sisi-Mu di syurga, dan selamatkanlah aku daripada Firaun.»"),
"prophets_083": ("Berapa malam pertemuan Allah dengan Musa di gunung berlangsung?", ["Empat puluh", "Tujuh", "Sepuluh", "Seratus"], "«Kami janjikan kepada Musa tiga puluh malam dan Kami sempurnakan dengan sepuluh: empat puluh malam.»"),
"prophets_084": ("Apakah yang berlaku apabila Musa memohon untuk melihat Allah?", ["Allah menampakkan diri kepada gunung, lalu ia hancur, dan Musa jatuh pengsan", "Dia melihat Allah", "Tiada apa yang berlaku", "Gunung itu naik ke langit"], "«Lihatlah gunung itu: jika ia tetap di tempatnya, engkau akan melihat-Ku.» Gunung itu hancur dan Musa jatuh pengsan."),
"prophets_085": ("Di atas apakah Allah menulis nasihat dan penjelasan untuk Musa?", ["Di atas Luh-luh (kepingan)", "Di atas daun kurma", "Di atas batu hitam", "Di atas kulit"], "«Kami tuliskan untuknya di atas Luh-luh nasihat tentang segala sesuatu.»"),
"prophets_086": ("Siapakah yang membuat anak lembu yang disembah Bani Israil ketika Musa tiada?", ["As-Samiri", "Harun", "Firaun", "Qarun"], "«As-Samiri telah menyesatkan mereka»: daripada perhiasan mereka dia membuat anak lembu yang mengeluarkan bunyi lenguhan."),
"prophets_087": ("Berapa mata air yang memancar daripada batu yang dipukul Musa dengan tongkatnya?", ["Dua belas", "Tujuh", "Tiga", "Empat puluh"], "«Pukullah batu itu dengan tongkatmu»: memancarlah dua belas mata air, satu untuk setiap suku."),
"prophets_088": ("Makanan apakah yang Allah turunkan kepada Bani Israil di padang pasir?", ["Manna dan burung salwa", "Nasi dan ikan", "Kurma dan susu", "Roti dan zaitun"], "«Kami turunkan kepada kamu manna dan salwa.»"),
"prophets_089": ("Apakah warna lembu yang Musa perintahkan Bani Israil sembelih?", ["Kuning terang", "Hitam", "Putih", "Merah"], "«Ia adalah lembu kuning, terang warnanya, menyenangkan orang yang melihatnya.»"),
"prophets_090": ("Siapakah daripada kaum Musa yang ditelan bumi bersama rumahnya kerana kesombongan dan kekayaannya?", ["Qarun", "Haman", "As-Samiri", "Jalut"], "Qarun memiliki khazanah yang sangat banyak; «Kami benamkan dia bersama rumahnya ke dalam bumi.»"),
"prophets_091": ("Logam apakah yang Allah lembutkan untuk Daud?", ["Besi", "Emas", "Tembaga", "Perak"], "«Dan Kami lembutkan besi untuknya.»"),
"prophets_092": ("Apakah yang Allah ajarkan Daud membuat, untuk melindungi manusia dalam peperangan?", ["Baju besi", "Pedang", "Perisai kayu", "Menara"], "«Kami ajarkan kepadanya membuat baju besi untuk melindungi kamu.»"),
"prophets_093": ("Gergasi manakah yang Daud bunuh dalam peperangan, menurut al-Quran?", ["Jalut", "Firaun", "Haman", "Namrud"], "«Dan Daud membunuh Jalut, dan Allah mengurniakannya kerajaan dan hikmah.»"),
"prophets_094": ("Bagaimanakah Raja Talut menguji tenteranya sebelum menghadapi Jalut?", ["Sebatang sungai: jangan minum daripadanya, kecuali seceduk tangan", "Perlumbaan", "Puasa tiga hari", "Mendaki gunung"], "«Allah akan menguji kamu dengan sebatang sungai: sesiapa yang minum daripadanya bukanlah daripada golonganku, kecuali yang menceduk seceduk tangan.»"),
"prophets_095": ("Apakah yang Allah jadikan bertasbih kepada-Nya bersama Daud?", ["Gunung-ganang dan burung-burung", "Angin", "Jin", "Ikan"], "«Dan Kami tundukkan gunung-ganang untuk bertasbih bersama Daud, dan juga burung-burung.»"),
"prophets_096": ("Unsur apakah yang Allah tundukkan kepada Sulaiman untuk membawanya ke mana sahaja dia mahu?", ["Angin", "Api", "Hujan", "Laut"], "«Dan kepada Sulaiman, angin yang bertiup kencang dengan perintahnya menuju ke negeri yang diberkati.»"),
"prophets_097": ("Burung apakah yang membawa berita kerajaan Saba' kepada Sulaiman?", ["Burung hud-hud", "Helang", "Merpati", "Gagak"], "Hud-hud kembali dan berkata: «Aku telah mengetahui sesuatu yang engkau tidak ketahui, dan aku membawa kepadamu berita yang pasti dari Saba'.»"),
"prophets_098": ("Makhluk kecil apakah yang memberi amaran kepada kaumnya supaya masuk ke sarang ketika tentera Sulaiman menghampiri?", ["Semut", "Lebah", "Tikus", "Labah-labah"], "Seekor semut berkata: «Wahai semut, masuklah ke sarang-sarang kamu, agar Sulaiman dan tenteranya tidak memijak kamu tanpa sedar.»"),
"prophets_099": ("Berapa pantas singgahsana Ratu Saba' dibawa kepada Sulaiman?", ["Sebelum matanya berkedip", "Dalam sehari", "Dalam tujuh hari", "Dalam sebulan"], "Orang yang mempunyai ilmu daripada Kitab berkata: «Aku akan membawanya kepadamu sebelum matamu berkedip.»"),
"prophets_100": ("Menurut al-Quran, apakah yang jin buat untuk Sulaiman?", ["Bangunan tinggi, patung dan kolam besar", "Permaidani terbang", "Kapal", "Gunung"], "«Mereka membuat untuknya apa yang dia kehendaki: bangunan-bangunan tinggi, patung-patung, bekas-bekas seperti kolam dan periuk-periuk yang tetap.»"),
"prophets_101": ("Bagaimanakah jin mengetahui kematian Sulaiman?", ["Makhluk bumi memakan tongkatnya lalu dia rebah", "Seorang malaikat memberitahu mereka", "Hud-hud memberitahu mereka", "Mereka melihatnya mati"], "Hanya «makhluk bumi» yang memakan tongkatnya mendedahkan kematiannya; jin pun sedar bahawa mereka tidak mengetahui perkara ghaib."),
"prophets_102": ("Apakah doa khusus yang Sulaiman panjatkan kepada Allah?", ["Kerajaan yang tidak dimiliki sesiapa pun selepasnya", "Umur yang panjang", "Kekayaan Qarun", "Kuasa untuk terbang"], "«Wahai Tuhanku, ampunilah aku dan kurniakanlah kepadaku kerajaan yang tidak dimiliki sesiapa pun selepasku.»"),
"prophets_103": ("Apakah yang Allah perintahkan Ayub lakukan untuk memulihkan kesihatannya?", ["Menghentakkan kakinya ke bumi: memancarlah mata air yang sejuk", "Berpuasa sebulan", "Mandi di laut", "Mendaki gunung"], "«Hentakkanlah kakimu: inilah mata air yang sejuk untuk mandi, dan untuk minum.»"),
"prophets_104": ("Apakah doa Yunus dalam kegelapan perut ikan?", ["«Tiada tuhan selain Engkau! Maha Suci Engkau, sesungguhnya aku termasuk orang yang zalim»", "«Wahai Tuhanku, berikanlah aku kerajaan»", "«Wahai Tuhanku, turunkanlah hujan kepadaku»", "«Wahai Tuhanku, izinkan aku melihat-Mu»"], "«Dia berseru dalam kegelapan: tiada tuhan selain Engkau! Maha Suci Engkau; sesungguhnya aku termasuk orang yang zalim.»"),
"prophets_105": ("Tumbuhan apakah yang Allah tumbuhkan di atas Yunus selepas ikan itu mencampakkannya keluar?", ["Pokok labu (yaqtin)", "Pokok kurma", "Pokok zaitun", "Pokok anggur"], "«Dan Kami tumbuhkan di atasnya sepohon pokok labu.»"),
"prophets_106": ("Kepada berapa orang Yunus diutuskan, menurut al-Quran?", ["Seratus ribu, atau lebih", "Seribu", "Sepuluh ribu", "Dua belas"], "«Dan Kami utuskan dia kepada seratus ribu orang, atau lebih.»"),
"prophets_107": ("Apakah tanda yang Allah berikan kepada Zakaria untuk mengesahkan kedatangan anaknya?", ["Tidak berbicara dengan manusia selama tiga malam, walaupun sihat", "Bintang jatuh", "Hujan pada musim panas", "Sebuah mimpi"], "«Tandamu ialah engkau tidak akan berbicara dengan manusia selama tiga malam, walaupun engkau sihat.»"),
"prophets_108": ("Apakah yang Allah katakan tentang nama Yahya?", ["Tiada sesiapa sebelumnya diberi nama itu", "Itu nama datuknya", "Ibunya yang memilihnya", "Itu nama seorang raja"], "«Kami khabarkan kepadamu berita gembira tentang seorang anak lelaki bernama Yahya; Kami belum pernah memberikan nama ini kepada sesiapa sebelumnya.»"),
"prophets_109": ("Apakah yang Allah kurniakan kepada Yahya ketika dia masih kanak-kanak?", ["Hikmah", "Kerajaan", "Seekor kuda", "Harta karun"], "«Wahai Yahya, ambillah Kitab itu dengan bersungguh-sungguh.» Dan Kami kurniakan kepadanya hikmah ketika dia masih kanak-kanak."),
"prophets_110": ("Apakah yang ibu Maryam nazarkan untuk anak yang dikandungnya?", ["Mempersembahkannya untuk berkhidmat kepada Allah", "Menghantarnya ke Mesir", "Menjadikannya raja", "Mengamanahkannya kepada seorang gembala"], "«Wahai Tuhanku, aku nazarkan kepada-Mu apa yang ada dalam kandunganku, dikhususkan untuk berkhidmat kepada-Mu.»"),
"prophets_111": ("Nabi manakah yang memelihara Maryam selepas kelahirannya?", ["Zakaria", "Yahya", "Isa", "Daud"], "«Dan Dia menjadikan Zakaria pemeliharanya», yang mendapati di sisinya rezeki daripada Allah."),
"prophets_112": ("Menurut al-Quran, Allah memilih Maryam melebihi siapa?", ["Wanita seluruh alam", "Para permaisuri", "Para malaikat", "Para nabi"], "«Wahai Maryam, sesungguhnya Allah telah memilihmu dan menyucikanmu, dan memilihmu melebihi wanita seluruh alam.»"),
"prophets_113": ("Apakah yang gugur untuk Maryam apabila dia menggoncang batang pokok kurma?", ["Kurma segar yang masak", "Zaitun", "Buah tin", "Hujan"], "«Goncanglah batang pokok kurma itu ke arahmu: ia akan menggugurkan kepadamu kurma yang segar lagi masak.»"),
"prophets_114": ("Perkataan apakah yang al-Quran gunakan untuk Maryam dalam surah Al-Ma'idah?", ["Siddiqah (wanita yang benar)", "Permaisuri", "Nabi wanita", "Pahlawan wanita"], "«Al-Masih putera Maryam hanyalah seorang rasul… dan ibunya seorang wanita yang benar (siddiqah).»"),
"prophets_115": ("Gelaran apakah yang al-Quran berikan kepada Isa putera Maryam?", ["Al-Masih", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "«Namanya Al-Masih Isa putera Maryam, terkemuka di dunia dan di akhirat.»"),
"prophets_116": ("Apakah yang Isa bentuk daripada tanah liat, dengan izin Allah?", ["Bentuk burung, yang kemudian hidup", "Sebuah rumah", "Patung seorang raja", "Sebuah perahu"], "«Aku membentuk untuk kamu daripada tanah liat seperti bentuk burung, kemudian aku tiup ke dalamnya lalu ia menjadi burung dengan izin Allah.»"),
"prophets_117": ("Apakah nama sahabat-sahabat karib Isa yang mengisytiharkan diri sebagai «penolong Allah»?", ["Al-Hawariyyun (para pengikut setia)", "Al-Ansar", "Al-Muhajirun", "As-Sahabah"], "«Para hawari berkata: kamilah penolong-penolong Allah.»"),
"prophets_118": ("Apakah yang para hawari minta daripada Isa, yang menjadi nama surah Al-Ma'idah?", ["Hidangan makanan yang diturunkan dari langit", "Sebuah kitab", "Sebuah kerajaan", "Emas"], "«Bolehkah Tuhanmu menurunkan kepada kami hidangan makanan dari langit?»"),
"prophets_119": ("Apakah yang al-Quran katakan tentang pengakhiran tugas Isa di bumi?", ["Dia tidak dibunuh dan tidak disalib: Allah mengangkatnya kepada-Nya", "Dia mati kerana tua", "Dia lemas", "Dia pergi ke Mesir"], "«Mereka tidak membunuhnya dan tidak menyalibnya… bahkan Allah mengangkatnya kepada-Nya.»"),
"prophets_120": ("Dengan nama apakah Isa mengkhabarkan seorang rasul yang akan datang selepasnya?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…membawa berita gembira tentang seorang rasul yang akan datang selepasku, namanya Ahmad.»"),
"prophets_121": ("Berhala apakah yang Nabi Ilyas tegur kaumnya kerana menyembahnya?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "«Adakah kamu menyeru Ba'l dan meninggalkan sebaik-baik pencipta?»"),
"prophets_122": ("Tiga orang nabi manakah yang al-Quran sebut bersama sebagai «termasuk orang yang sabar»?", ["Ismail, Idris dan Zulkifli", "Nuh, Hud dan Salih", "Musa, Harun dan Yusya'", "Daud, Sulaiman dan Ayub"], "«Dan Ismail, Idris dan Zulkifli: semuanya termasuk orang yang sabar.»"),
"prophets_123": ("Nabi manakah yang disebut dalam surah Sad bersama Ismail dan Zulkifli?", ["Al-Yasa'", "Yunus", "Lut", "Syuaib"], "«Dan ingatlah Ismail, Al-Yasa' dan Zulkifli: semuanya termasuk orang-orang yang terbaik.»"),
"prophets_124": ("Gelaran apakah yang al-Quran berikan kepada Nabi Muhammad ﷺ dalam ayat 33:40?", ["Penutup para nabi", "Raja orang Arab", "Bapa orang beriman", "Sahabat Allah"], "«Muhammad… adalah Rasulullah dan penutup para nabi.»"),
"prophets_125": ("Menurut al-Quran, sebagai apakah Nabi Muhammad ﷺ diutuskan?", ["Rahmat bagi sekalian alam", "Seorang raja", "Seorang hakim", "Seorang pahlawan"], "«Kami tidak mengutusmu melainkan sebagai rahmat bagi sekalian alam.»"),
"prophets_126": ("Menurut ayat 33:56, apakah yang Allah dan para malaikat-Nya lakukan untuk Nabi ﷺ?", ["Berselawat ke atasnya", "Melindunginya daripada angin", "Menghantar hujan kepadanya", "Memerhatikannya dalam diam"], "«Sesungguhnya Allah dan para malaikat-Nya berselawat ke atas Nabi. Wahai orang beriman, berselawatlah kamu ke atasnya dan ucapkanlah salam.»"),
"prophets_127": ("Bagaimanakah al-Quran menggambarkan akhlak Nabi ﷺ dalam surah Al-Qalam?", ["«Engkau benar-benar berakhlak agung»", "«Engkau seorang raja yang hebat»", "«Engkau yang paling kaya»", "«Engkau yang paling kuat»"], "«Dan sesungguhnya engkau benar-benar berakhlak agung.»"),
"prophets_128": ("Apakah yang ayat 3:144 ingatkan kita tentang Muhammad ﷺ?", ["Dia hanyalah seorang rasul, dan rasul-rasul telah berlalu sebelumnya", "Dia tidak akan mati", "Dia seorang malaikat", "Dia mengetahui masa depan"], "«Muhammad hanyalah seorang rasul; sungguh telah berlalu rasul-rasul sebelumnya.»"),
"prophets_129": ("Lima orang nabi manakah yang ayat 33:7 sebut bersama untuk perjanjian yang teguh?", ["Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ", "Adam, Nuh, Hud, Salih dan Lut", "Daud, Sulaiman, Ayub, Yunus dan Idris", "Ismail, Ishak, Yaakub, Yusuf dan Musa"], "«Kami mengambil perjanjian daripada para nabi: daripadamu, daripada Nuh, Ibrahim, Musa dan Isa putera Maryam.»"),
"prophets_130": ("Menurut hadis dalam al-Bukhari, pekerjaan apakah yang dilakukan setiap nabi?", ["Menggembala kambing", "Tukang kayu", "Tukang besi", "Pedagang"], "«Allah tidak mengutuskan seorang nabi pun melainkan dia menggembala kambing», dan Nabi ﷺ menggembalanya untuk penduduk Makkah."),
"prophets_131": ("Menurut hadis dalam Muslim, nabi manakah yang bekerja sebagai tukang kayu?", ["Zakaria", "Nuh", "Idris", "Yusuf"], "Nabi ﷺ bersabda: «Zakaria adalah seorang tukang kayu.»"),
"prophets_132": ("Nabi manakah yang Nabi ﷺ katakan bahawa baginda «orang yang paling dekat» dengannya, di dunia dan di akhirat?", ["Isa putera Maryam", "Musa", "Ibrahim", "Nuh"], "«Aku adalah orang yang paling dekat dengan Isa putera Maryam di dunia dan di akhirat; para nabi itu bersaudara.»"),
"prophets_133": ("Berapa surah dalam al-Quran yang dinamakan sempena seorang nabi?", ["Enam", "Dua", "Dua belas", "Dua puluh lima"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) dan Nuh (71)."),
"prophets_134": ("Dengan tiga sifat apakah al-Quran menggambarkan Ibrahim dalam ayat 11:75?", ["Penyantun, lembut hati, sentiasa kembali kepada Allah", "Kaya, berkuasa, berilmu", "Kuat, pantas, berani", "Raja, hakim, pahlawan"], "«Sesungguhnya Ibrahim itu penyantun, lembut hati dan sentiasa kembali kepada Allah.»"),
"prophets_135": ("Apakah yang Syuaib tegur kaumnya, selain penyembahan berhala?", ["Menipu dalam sukatan dan timbangan", "Tidak bersolat", "Bermusafir pada waktu malam", "Makan ikan"], "«Sempurnakanlah sukatan dan timbangan, dan janganlah kamu kurangkan hak manusia.»"),
"prophets_136": ("Apakah yang menimpa kaum Syuaib selepas mereka menolak dakwahnya?", ["Gempa bumi", "Banjir besar", "Hujan api", "Kawanan burung"], "«Maka gempa bumi menimpa mereka, lalu mereka mati bergelimpangan di dalam rumah mereka.»"),
"prophets_137": ("Apakah berita yang para malaikat sampaikan kepada Ibrahim selepas menenangkan ketakutannya?", ["Bahawa mereka diutus kepada kaum Lut", "Bahawa banjir besar akan datang", "Bahawa Kaabah akan dimusnahkan", "Bahawa Firaun akan lemas"], "«Janganlah takut: kami diutus kepada kaum Lut.»"),
"prophets_138": ("Apakah yang Ibrahim pohon untuk dirinya dan zuriatnya dalam ayat 14:40?", ["Menjadi orang yang mendirikan solat", "Menjadi raja", "Menjadi kaya", "Hidup lama"], "«Wahai Tuhanku, jadikanlah aku orang yang mendirikan solat, dan juga daripada zuriatku.»"),
"prophets_139": ("Pada akhir kisah Yusuf, siapakah yang dia naikkan ke atas singgahsana sebelum semua sujud kepadanya?", ["Kedua ibu bapanya", "Raja", "Saudara-saudaranya", "Anaknya"], "«Dia menaikkan kedua ibu bapanya ke atas singgahsana, dan mereka tersungkur sujud kepadanya»: mimpi zaman kanak-kanak menjadi kenyataan."),
"prophets_140": ("Mengapakah saudara-saudara Yusuf mahu menyingkirkannya?", ["Kerana cemburu: bapa mereka lebih menyayanginya", "Dia telah mencuri", "Dia enggan bekerja", "Dia sakit"], "«Yusuf dan saudaranya lebih disayangi ayah kita daripada kita… Bunuhlah Yusuf atau buanglah dia ke suatu tempat.»"),
"prophets_141": ("Apakah yang saudara-saudara Yusuf bawa kepada bapa mereka untuk meyakinkannya bahawa serigala telah memakannya?", ["Bajunya yang dilumuri darah palsu", "Kasutnya", "Tongkatnya", "Gigi serigala"], "«Mereka datang membawa bajunya yang berlumuran darah palsu»; Yaakub menjawab: «Kesabaran yang baik itulah yang terbaik.»"),
"prophets_142": ("Apakah yang Allah janjikan kepada ibu Musa ketika mengilhamkannya meletakkan bayi itu di sungai?", ["Mengembalikannya kepadanya dan menjadikannya seorang rasul", "Memberinya anak lelaki yang lain", "Menjadikannya permaisuri", "Menurunkan hujan"], "«Janganlah takut dan janganlah bersedih: Kami akan mengembalikannya kepadamu dan menjadikannya salah seorang rasul.»"),
"prophets_143": ("Dengan apakah Musa memukul laut sehingga ia terbelah?", ["Tongkatnya", "Tangannya", "Sebiji batu", "Pedangnya"], "«Pukullah laut itu dengan tongkatmu»: ia terbelah, dan setiap bahagiannya seperti gunung yang besar."),
"prophets_144": ("Apakah perkara pertama yang Allah firmankan kepada Musa ketika berbicara dengannya?", ["«Akulah Allah, tiada tuhan selain Aku: sembahlah Aku dan dirikanlah solat»", "«Pergilah memancing»", "«Binalah bahtera»", "«Kembalilah kepada Firaun»"], "«Sesungguhnya Akulah Allah; tiada tuhan selain Aku, maka sembahlah Aku dan dirikanlah solat untuk mengingati-Ku.»"),
"prophets_145": ("Bagaimanakah Allah menyuruh Musa dan Harun berbicara kepada Firaun?", ["Dengan kata-kata yang lembut", "Dengan marah", "Dengan menjerit", "Dengan diam"], "«Pergilah kamu berdua kepada Firaun… dan berbicaralah kepadanya dengan kata-kata yang lembut; mudah-mudahan dia ingat atau takut.»"),
"prophets_146": ("Apakah yang Musa katakan kepada pembantu mudanya pada awal perjalanan ke pertemuan dua laut?", ["Bahawa dia tidak akan berhenti sehingga sampai ke pertemuan dua laut", "Bahawa dia mahu pulang", "Bahawa dia takut", "Bahawa dia mencari emas"], "«Aku tidak akan berhenti sehingga sampai ke pertemuan dua laut, walaupun aku berjalan bertahun-tahun.»"),
"prophets_147": ("Antara berikut, apakah yang dilakukan hamba yang berilmu itu di hadapan Musa, yang ketika itu tidak memahaminya?", ["Dia membocorkan sebuah perahu", "Dia membina jambatan", "Dia menyalakan api", "Dia menanam pokok"], "Dia membocorkan perahu, kemudian membunuh seorang budak, kemudian menegakkan sebuah dinding, dan selepas itu menjelaskan setiap perbuatan kepada Musa."),
"prophets_148": ("Apakah kata-kata pertama Isa, ketika masih dalam buaian?", ["«Aku hamba Allah; Dia memberiku Kitab dan menjadikanku nabi»", "«Aku anak Tuhan»", "«Aku seorang raja»", "«Aku lapar»"], "«Dia berkata: sesungguhnya aku hamba Allah. Dia memberiku Kitab dan menjadikanku nabi.»"),
"prophets_149": ("Apakah yang Adam dan isterinya katakan kepada Allah selepas makan daripada pokok itu?", ["«Wahai Tuhan kami, kami telah menzalimi diri kami; jika Engkau tidak mengampuni kami, kami akan rugi»", "«Bukan salah kami»", "«Itu salah pokok itu»", "Mereka tidak berkata apa-apa"], "«Wahai Tuhan kami, kami telah menzalimi diri kami sendiri, dan jika Engkau tidak mengampuni kami dan merahmati kami, nescaya kami termasuk orang yang rugi.»"),
"prophets_150": ("Apakah tugas yang Allah berikan kepada Nuh terhadap kaumnya, dalam ayat pertama surah Nuh?", ["Memberi amaran kepada mereka sebelum datang azab yang pedih", "Membina sebuah kota", "Mengajar mereka memancing", "Menjadikan mereka raja"], "«Kami mengutuskan Nuh kepada kaumnya: berilah amaran kepada kaummu sebelum datang kepada mereka azab yang pedih.»"),
}
